NAME = 'CzeCSP: Czech Český studijní překlad'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: 'Počátek evangelia Ježíše Krista, [Syna Božího] ⌈.',
        2: 'Jak⌉ je napsáno ⌈v proroku Izaiášovi⌉: Hle, [já] posílám svého posla před tvou tváří, který upraví tvou cestu [před tebou].',
        3: 'Hlas volajícího v pustině: Připravte Pánovu cestu, vyrovnávejte jeho stezky.',
        4: 'Objevil se Jan, který křtil v pustině a hlásal křest pokání na odpuštění hříchů.',
        5: 'A vycházela k němu celá judská krajina a všichni jeruzalémští a dávali se od něho pokřtít v řece Jordánu, vyznávajíce své hříchy.',
        6: 'Jan byl oděn velbloudí srstí a přepásán koženým pásem kolem svých beder a jedl kobylky a polní med.',
        7: 'Hlásal: „Za mnou přichází někdo silnější než já; nejsem hoden sklonit se a rozvázat řemínek jeho sandálů.',
        8: 'Já ⌈jsem vás křtil⌉ ve vodě, ale on vás bude křtít v Duchu Svatém.“',
        9: 'V těch dnech přišel Ježíš z Nazareta v Galileji a byl pokřtěn od Jana v Jordánu.',
        10: 'A hned když vystupoval z vody, uviděl roztrhávající se nebesa a Ducha jako holubici, jak sestupuje ⌈k němu⌉.',
        11: 'A z nebes [zazněl] hlas: „Ty jsi ⌈můj Syn, Milovaný,⌉ v tobě jsem nalezl zalíbení.“',
        12: 'A hned ho Duch vypudil do pustiny.',
        13: 'V té pustině byl čtyřicet dní pokoušen Satanem. Byl tam s dravou zvěří a andělé mu sloužili.',
        14: 'Po Janově uvěznění přišel Ježíš do Galileje a hlásal evangelium Boží.',
        15: 'A říkal: „Naplnil se čas a přiblížilo se Boží království; čiňte pokání a věřte evangeliu.“',
        16: 'A když šel podél Galilejského moře, uviděl Šimona a Šimonova bratra Ondřeje, jak do moře vrhají [síť]; byli totiž rybáři.',
        17: 'Ježíš jim řekl: „Pojďte za mnou a učiním, že se stanete rybáři lidí.“',
        18: 'A hned opustili sítě a následovali ho.',
        19: 'A když šel kousek dál, uviděl Jakuba Zebedeova a jeho bratra Jana, jak v lodi spravují sítě.',
        20: 'A hned je povolal. Zanechali svého otce Zebedea v lodi s najatými pomocníky a odešli za ním.',
        21: 'I vešli do Kafarnaum. Hned v sobotu vstoupil do synagogy a učil.',
        22: 'Byli ohromeni jeho vyučováním, neboť je učil jako ten, kdo má pravomoc, a ne jako učitelé Zákona.',
        23: 'V jejich synagoze byl [právě] člověk ⌈s nečistým duchem⌉. Vykřikl:',
        24: '„⌈Co je ti po nás⌉, Ježíši Nazaretský? Přišel jsi nás zničit? Znám tě, vím, kdo jsi: Ten Svatý Boží.“',
        25: 'Ježíš mu pohrozil: „Umlkni a vyjdi z něho.“',
        26: 'A ten nečistý duch jím zalomcoval, zvolal silným hlasem a vyšel z něho.',
        27: 'Všichni užasli, takže se dohadovali mezi sebou, říkajíce: „Co to je? ⌈Nové učení! S pravomocí⌉ dokonce přikazuje nečistým duchům, a poslouchají ho!“',
        28: 'A pověst o něm ⌈se hned rozšířila⌉ [všude] po celém okolí Galileje.',
        29: 'A hned, když ⌈vyšli ze synagogy, přišli⌉ s Jakubem a Janem do domu Šimona a Ondřeje.',
        30: 'Šimonova tchyně ležela ⌈v horečce⌉. Hned mu o ní pověděli.',
        31: 'Ježíš přistoupil, uchopil [její] ruku a pozdvihl ji. [Ihned] ji horečka opustila a ona je obsluhovala.',
        32: 'Když nastal večer a slunce zapadlo, přinášeli k němu všechny nemocné a všechny démonizované.',
        33: 'Celé město se shromáždilo přede dveřmi.',
        34: 'I uzdravil mnoho trpících rozličnými chorobami a vyhnal mnoho démonů. A těm démonům nedovoloval mluvit, neboť ho znali.',
        35: 'Časně ráno, ještě za tmy, vstal a vyšel ven; odešel na opuštěné místo a tam se modlil.',
        36: 'Šimon a ti, kteří byli s ním, se pustili spěšně za ním.',
        37: '⌈Když ho našli,⌉ řekli mu: „Všichni tě hledají.“',
        38: 'Říká jim: „Pojďme jinam, do sousedních městeček, abych i tam hlásal evangelium, neboť kvůli tomu jsem vyšel.“',
        39: 'A hlásal evangelium v jejich synagogách po celé Galileji a vyháněl démony.',
        40: 'Tu k němu přišel malomocný, padl [před ním] na kolena a prosil ho: „Chceš–li, jsi mocen mne očistit.“',
        41: 'Ježíš, hluboce pohnut, vztáhl svou ruku, dotkl se ho a řekl mu: „Chci, buď očištěn.“',
        42: 'A [když to řekl,] hned od něho malomocenství odešlo a byl očištěn.',
        43: 'Ježíš mu přísně domluvil a hned ho poslal pryč.',
        44: 'Řekl mu: „Hleď, abys nikomu nic neřekl! Ale jdi, ukaž se knězi a obětuj za své očištění, co nařídil Mojžíš, jim na svědectví.“',
        45: 'On však vyšel a začal to velice rozhlašovat a rozšiřovat, takže Ježíš již nemohl veřejně vstoupit do města, ale zůstával venku na opuštěných místech. A přicházeli k němu odevšad.',
    },
    2: {
        1: 'A když po několika dnech opět vstoupil do Kafarnaum, rozneslo se, že je doma.',
        2: 'A [hned] se shromáždilo mnoho lidí, takže už nebylo místo ani přede dveřmi. A mluvil k nim Slovo.',
        3: 'Tu přicházeli lidé a nesli k němu ochrnutého; nesli ho čtyři.',
        4: 'A ⌈protože ho k němu pro zástup nemohli přinést⌉, odkryli střechu tam, kde byl, prorazili otvor a lehátko, na kterém ochrnutý ležel, spustili dolů.',
        5: 'Když Ježíš viděl jejich víru, řekl ochrnutému: „Synu, ⌈tvé hříchy jsou odpuštěny⌉.“',
        6: 'Seděli tam někteří z učitelů Zákona a uvažovali ve svých srdcích:',
        7: '„Proč takhle mluví? Rouhá se! Kdo je mocen odpouštět hříchy, ne–li jediný: Bůh.“',
        8: 'Ježíš hned svým duchem poznal, že takto uvažují, a řekl jim: „Proč tak uvažujete ve svých srdcích?',
        9: 'Co je snadnější? Říci ochrnutému: ⌈Tvé hříchy jsou odpuštěny⌉, nebo říci: Vstaň, vezmi své lehátko a choď?',
        10: 'Abyste však věděli, že Syn člověka má pravomoc odpouštět hříchy na zemi …“, říká ochrnutému:',
        11: '„Tobě pravím: Vstaň, vezmi své lehátko a jdi do svého domu.“',
        12: 'On vstal, vzal hned své lehátko a přede všemi vyšel, takže tím byli všichni ohromeni, oslavovali Boha a říkali: „Něco takového jsme ještě nikdy neviděli.“',
        13: 'Ježíš opět vyšel podél moře a celý ten zástup k němu přicházel a on je vyučoval.',
        14: 'Cestou uviděl Léviho, syna Alfeova, sedícího v celnici, a řekl mu: „Následuj mne.“On vstal a následoval ho.',
        15: 'A když Ježíš stoloval v jeho domě, mnozí celníci a hříšníci stolovali spolu s Ježíšem a jeho učedníky, neboť jich bylo mnoho a následovali ho.',
        16: 'Když učitelé Zákona ⌈z farizeů⌉ viděli, že jí s hříšníky a celníky, říkali jeho učedníkům: „Jak to, že jí [a pije] s celníky a hříšníky?“',
        17: 'Když to Ježíš uslyšel, řekl jim: „Lékaře nepotřebují zdraví, nýbrž nemocní. Nepřišel jsem povolat spravedlivé, ale hříšné.“',
        18: 'Janovi učedníci a farizeové se právě postili. I přijdou k němu a říkají: „Proč se Janovi učedníci a učedníci farizeů postí, ale tvoji učedníci se nepostí?“',
        19: 'Ježíš jim řekl: „Mohou se svatebčané postit, když je ženich s nimi? Dokud mají ženicha s sebou, nemohou se postit.',
        20: 'Přijdou však dny, kdy jim bude ženich odebrán, a tehdy v onen den se budou postit.“',
        21: '„Nikdo nepřišívá záplatu z neseprané látky na starý šat, jinak se ta výplň odtrhne, nové od starého, a trhlina se ještě zhorší.',
        22: 'A nikdo nedává mladé víno do starých měchů, jinak víno ty měchy roztrhne a víno [se vylije] a měchy se zničí. Ale mladé víno [se má dávat] do nových měchů!“',
        23: 'I stalo se, že v sobotu procházel obilím a jeho učedníci začali cestou trhat klasy.',
        24: 'Farizeové mu řekli: „Podívej, proč dělají v sobotu, co se nesmí?“',
        25: 'Ježíš jim říká: „Nikdy jste nečetli, co udělal David, když se ocitl v nouzi a dostal hlad, on i ti, kdo byli s ním?',
        26: 'Jak za velekněze Abiatara vešel do domu Božího a snědl chleby předložení, které nesmí jíst nikdo kromě kněží, a dal i těm, kteří byli s ním?“',
        27: 'A řekl jim: „Sobota byla učiněna pro člověka, a ne člověk pro sobotu.',
        28: 'Takže Syn člověka je také pánem soboty.“',
    },
    3: {
        1: 'Vstoupil opět do synagogy. A byl tam člověk, který měl odumřelou ruku.',
        2: 'Pozorně jej sledovali, zda ho v sobotu uzdraví, aby jej obžalovali.',
        3: 'A on tomu člověku s odumřelou rukou řekl: „Postav se doprostřed.“',
        4: 'A jim řekl: „Je v sobotu dovoleno učinit dobře, nebo zle, duši zachránit, nebo zahubit?“Ale oni mlčeli.',
        5: 'Rozhněvaně se po nich rozhlédl a hluboce zarmoucen nad tvrdostí jejich srdce řekl tomu člověku: „Natáhni [svou] ruku.“Natáhl ji, a jeho ruka byla uzdravena.',
        6: 'Když farizeové vyšli, hned se s herodiány proti němu radili, jak by ho zahubili.',
        7: 'Ježíš se se svými učedníky odebral k moři. A vydalo se za [ním] velké množství lidí z Galileje a z Judska.',
        8: 'Také z Jeruzaléma, z Idumeje a Zajordání, z okolí Týru a Sidónu přišlo k němu velké množství lidí, když slyšeli, co všechno činil.',
        9: 'Řekl tedy svým učedníkům, aby pro něj měli stále připravenou loďku, aby se na něho zástup netlačil.',
        10: 'Neboť mnohé uzdravil, takže všichni, kteří měli trápení, se k němu hrnuli, aby se ho dotkli.',
        11: 'A nečistí duchové, kdykoli ho viděli, padali před ním a křičeli: „Ty jsi Syn Boží!“',
        12: 'Ostře je káral, aby nezjevili, kdo je.',
        13: 'Vystoupil na horu a zavolal k sobě ty, které sám chtěl. I odešli k němu.',
        14: 'Ustanovil jich dvanáct, aby byli s ním, aby je posílal hlásat evangelium',
        15: 'a aby měli pravomoc vyhánět démony.',
        16: '[Ustanovil těchto Dvanáct:] Šimona, kterému přidal jméno Petr,',
        17: 'Jakuba Zebedeova a Jakubova bratra Jana a přidal jim jméno Boanerges, což znamená synové hromu,',
        18: 'Ondřeje, Filipa, Bartoloměje, Matouše, Tomáše, Jakuba, toho Alfeova, Tadeáše, Šimona Kananejského',
        19: 'a Judu Iškariotského, který ho pak zradil.',
        20: 'Přišli do domu a opět se shromáždil zástup, takže nemohli ani chleba pojíst.',
        21: 'Když to uslyšeli jeho příbuzní, vyšli, aby se ho zmocnili, neboť říkali: „Pomátl se.“',
        22: 'Učitelé Zákona, kteří sestoupili z Jeruzaléma, říkali: „Má Belzebula. ⌈V moci ⌉ vládce démonů vyhání démony!“',
        23: 'Zavolal je k sobě a mluvil k nim v podobenstvích: „Jak může Satan vyhánět Satana?',
        24: 'Je–li království proti sobě rozděleno, takové království nemůže obstát.',
        25: 'Bude–li dům proti sobě rozdělen, takový dům nebude moci obstát.',
        26: 'Jestliže Satan povstal sám proti sobě a rozdělil se, nemůže obstát, ale je s ním konec.',
        27: 'Avšak nikdo nemůže vejít do domu siláka a uloupit jeho majetek, jestliže siláka nejdříve nespoutá, a teprve pak vyloupí jeho dům.',
        28: '⌈Amen, pravím⌉ vám, že všechno bude lidským synům odpuštěno, prohřešení i rouhání, jakkoliv by se rouhali.',
        29: 'Kdo by však ⌈vědomě promluvil zle⌉ proti Duchu Svatému, nemá odpuštění v tomto věku, ale je vinen věčným prohřešením.“',
        30: 'Říkali totiž: „Má nečistého ducha.“',
        31: 'Tu přichází jeho matka a jeho bratři a stojíce venku ⌈dali ho zavolat⌉.',
        32: 'Kolem něho seděl zástup. Říkají mu: „Hle, tvá matka a tvoji bratři [a tvé sestry] tě venku hledají.“',
        33: '⌈Odpověděl jim⌉: „Kdo je má matka a moji bratři?“',
        34: 'A rozhlédl se po těch, kteří seděli v kruhu kolem něho, a řekl: „Hle, má matka a moji bratři.',
        35: 'Neboť kdo činí Boží vůli, to je můj bratr, má sestra i matka.“',
    },
    4: {
        1: 'A opět začal učit u moře. A shromáždil se k němu veliký zástup, takže vstoupil do lodi na moři a posadil se; celý ten zástup byl u moře na břehu.',
        2: 'A učil je mnohému v podobenstvích. Ve svém vyučování jim říkal:',
        3: '„Poslouchejte! Hle, rozsévač vyšel zasít.',
        4: 'A když rozséval, stalo se, že některé zrno padlo podél cesty; i přiletěli ptáci a sezobali je.',
        5: 'A jiné padlo na skalnaté místo, kde nemělo mnoho země, a hned vzešlo, protože nemělo hlubokou zem.',
        6: 'Když vyšlo slunce, spálilo je; a protože nemělo kořen, uschlo.',
        7: 'Jiné padlo do trní; trní vzešlo a udusilo je, a zrno nevydalo úrodu.',
        8: 'A jiná padla do dobré země, vzcházela, rostla a vydávala úrodu; a neslo jedno úrodu třicet inásobnou, jedno šedesát inásobnou a jedno sto násobnou.“',
        9: 'A říkal: „Kdo má uši k slyšení, ať poslouchá!“',
        10: 'Když se ocitl o samotě, ptali se ho ti, kdo byli s ním, spolu s Dvanácti, na ta podobenství.',
        11: 'Říkal jim: „Vám je dáno tajemství Božího království, avšak těm, kteří jsou vně, se to všechno děje v podobenstvích,',
        12: 'aby hledíce hleděli a neuviděli, slyšíce slyšeli a nechápali, neobrátili se ⌈a nebylo jim odpuštěno.⌉“',
        13: 'A řekl jim: „Nerozumíte tomuto podobenství; jak budete chápat všechna ta podobenství?',
        14: 'Rozsévač rozsévá Slovo.',
        15: 'Tito pak jsou podél cesty, kde se rozsévá Slovo: Když je uslyší, hned přichází Satan a bere Slovo ⌈do nich⌉ zaseté.',
        16: 'A [podobně] tito jsou na skalnatá místa zaséváni: Ti, když uslyší Slovo, hned je s radostí přijímají.',
        17: 'A nemají v sobě kořen, ale jsou nestálí. Když nastane soužení nebo pronásledování pro Slovo, ihned odpadají.',
        18: 'A další jsou ti, kteří jsou rozséváni do trní: To jsou ti, kteří uslyšeli Slovo,',
        19: 'ale potom přicházejí starosti toho to věku, svod bohatství a žádosti po ostatních věcech a dusí Slovo, takže se stává neplodným.',
        20: 'Ale tito jsou na dobrou zem zaseti: Slyší Slovo, přijímají je a nesou úrodu, jedni třicet inásobnou, jedni šedesát inásobnou a jedni sto násobnou.“',
        21: 'A říkal jim: „Zdali přinášejí lampu, aby ji postavili pod nádobu nebo pod postel? Ne proto, aby ji postavili na stojan?',
        22: 'Vždyť [nic] není skryté, než aby bylo zjeveno; ani nic nebylo ukryto, leč aby vyšlo najevo.',
        23: 'Má–li kdo uši k slyšení, ať poslouchá.“',
        24: 'A říkal jim: „Dávejte pozor, co slyšíte. Jakou měrou měříte, takovou bude naměřeno vám a bude vám přidáno.',
        25: 'Neboť kdo má, tomu bude dáno, a tomu, kdo nemá, bude odňato i to, co má.“',
        26: 'A říkal: „S Božím královstvím je to tak, jako když člověk hodí semeno na zem;',
        27: 'v noci spí a ve dne vstává a semeno klíčí a roste, on ani neví jak.',
        28: 'Země sama od sebe plodí, nejprve stéblo, potom klas, potom plné obilí v klasu.',
        29: 'A když úroda dozraje, člověk hned posílá srp, neboť nastala sklizeň.“',
        30: 'A říkal: „K čemu přirovnáme Boží království nebo jakým podobenstvím je znázorníme?',
        31: 'Je jako zrno hořčice. Když je zaseto do země, je menší než všechna semena na zemi.',
        32: 'A když je zaseto, vzchází a stává se větším než všechny zahradní byliny a vytváří velké ratolesti, takže ⌈v jeho stínu⌉ mohou hnízdit nebeští ptáci.“',
        33: 'A v mnoha takových podobenstvích k nim mluvil Slovo, jak byli schopni slyšet.',
        34: 'Bez podobenství k nim nemluvil, ale v soukromí svým učedníkům všechno vysvětloval.',
        35: 'Toho dne, když nastal večer, jim říká: „Přeplavme se na druhou stranu.“',
        36: 'Opustili zástup a vzali ho v té lodi, v níž byl; byly s ním také jiné lodě.',
        37: 'Tu nastala veliká větrná bouře a vlny se přelévaly do lodě, takže se loď již naplňovala.',
        38: 'A on spal na zádi na podušce. Vzbudili ho a řekli mu: „Učiteli, nezajímá tě, že hyneme?“',
        39: 'Probudil se, pohrozil větru a řekl moři: „Mlč, buď zticha!“A vítr přestal a nastal úplný klid.',
        40: 'Řekl jim: „Proč jste [tak] ustrašení? Ještě nemáte víru?“',
        41: 'Padla na ně veliká bázeň a říkali jeden druhému: „Kdo to tedy je, že ho poslouchají i vítr i moře?“',
    },
    5: {
        1: 'Přišli na druhou stranu moře do krajiny Gerasenů.',
        2: 'A jak vystoupil z lodi, hned proti němu z hrobů vyšel člověk ⌈s nečistým duchem⌉,',
        3: 'který měl v hrobech obydlí. Ani řetězy ho již nikdo nemohl spoutat,',
        4: 'neboť byl častokrát spoután okovy a řetězy, ale on vždy řetězy na sobě roztrhal a okovy rozlámal. Nikdo ho nedokázal zkrotit.',
        5: 'A stále dnem i nocí mezi hroby a na horách řval a sekal se kameny.',
        6: 'Když Ježíše z dálky uviděl, přiběhl a poklonil se mu',
        7: 'a silným hlasem zařval: „Co je ti po mně, Ježíši, synu Boha Nejvyššího? Zapřísahám tě při Bohu, netrýzni mne!“',
        8: 'Ježíš mu totiž říkal: „Duchu nečistý, vyjdi z toho člověka!“',
        9: 'A tázal se ho: „Jaké je tvé jméno?“Řekl mu: „Mé jméno je Legie, protože je nás mnoho.“',
        10: 'A velice ho prosil, aby je neposlal pryč z toho kraje.',
        11: 'Tam u hory se páslo veliké stádo vepřů.',
        12: '[Všichni ti démoni] ho poprosili: „Pošli nás do těch vepřů, abychom do nich vstoupili.“',
        13: 'On jim to dovolil. Nečistí duchové vyšli a vstoupili do těch vepřů. A stádo se zřítilo po svahu do moře, asi dva tisíce kusů, a utopilo se v moři.',
        14: 'Ti, kteří je pásli, utekli a oznámili to ve městě i ve vesnicích. A lidé přišli, aby se podívali, co se stalo.',
        15: 'Přišli k Ježíši a pozorovali toho démonizovaného, jak sedí oblečený a má zdravou mysl -- toho, který měl Legii -- a ulekli se.',
        16: 'A ti, kteří to viděli, jim popsali, jak se to stalo tomu démonizovanému a to o těch vepřích.',
        17: 'Začali ho prosit, aby odešel z jejich území.',
        18: 'Když vstupoval do lodi, prosil ho ten, který byl předtím démonizovaný, aby mohl být s ním.',
        19: 'Nedovolil mu to, ale řekl mu: „Jdi domů ke svým a oznam jim, jak veliké věci ti učinil Pán a jak se nad tebou slitoval.“',
        20: 'On odešel a začal v Dekapoli hlásat, jak veliké věci mu učinil Ježíš; a všichni se divili.',
        21: 'Když se Ježíš přeplavil [v lodi] opět na druhou stranu, shromáždil se k němu velký zástup; a byl u moře.',
        22: 'A [hle], přišel jeden z představených synagogy, jménem Jairos. Když Ježíše spatřil, padl k jeho nohám',
        23: 'a velmi ho prosil: „Má dceruška umírá! Pojď a vlož na ni ruce, aby byla zachráněna a ožila.“',
        24: 'Ježíš odešel s ním. Následoval ho velký zástup a tlačili se na něho.',
        25: 'A byla tam žena, která měla dvanáct let krvotok.',
        26: 'Mnoho vytrpěla od mnoha lékařů a vynaložila všechny své prostředky, nic jí to však neprospělo, ale spíše jí bylo hůře.',
        27: 'Když uslyšela o Ježíši, přišla v zástupu zezadu a dotkla se jeho šatu.',
        28: 'Neboť si říkala: „Jestliže se dotknu třeba jen jeho šatů, budu zachráněna.“',
        29: 'A hned vyschl pramen její krve a pocítila na těle, že je uzdravena ze svého trápení.',
        30: 'Ježíš hned v sobě rozpoznal tu moc, která z něho vyšla, otočil se v zástupu a řekl: „Kdo se dotkl mých šatů?“',
        31: 'Jeho učedníci mu řekli: „Vidíš, jak se na tebe zástup tlačí, a říkáš: Kdo se mne dotkl?“',
        32: 'Ježíš se rozhlížel, aby spatřil tu, která to učinila.',
        33: 'Žena se ulekla, a protože věděla, co se jí stalo, s třesením přišla a padla před ním a řekla mu celou pravdu.',
        34: 'A on jí řekl: „Dcero, tvá víra tě zachránila. Jdi v pokoji a buď uzdravená ze svého trápení.“',
        35: 'Zatímco ještě mluvil, přišli z domu představeného synagogy a říkali: „Tvá dcera zemřela; proč ještě obtěžuješ Učitele?“',
        36: 'Ale Ježíš neposlechl ⌈to, co říkali⌉, a řekl představenému synagogy: „Neboj se, jen věř!“',
        37: 'A nedovolil nikomu s ním jít, kromě Petra, Jakuba a Jakubova bratra Jana.',
        38: 'Přišli do domu představeného synagogy a Ježíš viděl rozruch a ty, kteří velice plakali a hlučně naříkali.',
        39: 'Vešel a řekl jim: „Proč se rozrušujete a pláčete? To dítě nezemřelo, ale spí.“',
        40: 'I posmívali se mu. Ale on všechny vyhnal a vzal s sebou otce a matku dítěte i ty, kteří byli s ním, a vešel tam, kde bylo dítě.',
        41: 'Uchopil ruku dítěte a řekl mu: „Talitha kúm“, což přeloženo znamená: Děvče, říkám ti, vstaň!',
        42: 'A děvče ihned vstalo a začalo chodit; bylo jí dvanáct let. A zmocnil se jich [ihned] veliký úžas.',
        43: 'Ježíš jim důrazně nařídil, aby se to nikdo nedověděl, a řekl, aby jí dali najíst.',
    },
    6: {
        1: 'Vyšel odtamtud a přišel do své vlasti; jeho učedníci ho doprovázeli.',
        2: 'Když nastala sobota, začal učit v synagoze. A mnozí, kteří ho slyšeli, byli ohromeni a říkali: „Odkud to tento člověk má? Jaká je to moudrost, která mu byla dána? A jaké mocné činy se dějí skrze jeho ruce!',
        3: 'Není to ten tesař, syn Marie a bratr Jakuba, Josese, Judy a Šimona, a nejsou jeho sestry zde s námi?“A pohoršovali se nad ním.',
        4: 'Ježíš jim říkal: „Prorok není beze cti, leda ve své vlasti, mezi svými příbuznými a ve svém domě.“',
        5: 'A nemohl tam učinit žádný mocný skutek, jen na několik neduživých vložil ruce a uzdravil je.',
        6: 'A divil se pro jejich nevěru. A procházel okolní vesnice a učil.',
        7: 'Zavolal si Dvanáct a začal je posílat dva a dva a dával jim pravomoc nad nečistými duchy.',
        8: 'Přikázal jim: „Neberte si nic na cestu, jen hůl, ne chleba, ani mošnu, ani měďáky do opasku,',
        9: 'ale mějte uvázané sandály a neoblékejte si dvojí spodní oděv.“',
        10: 'A říkal jim: „Kdekoli vstoupíte do domu, tam zůstávejte, dokud odtamtud neodejdete.',
        11: 'A když by vás ⌈některé místo nepřijalo⌉ a neposlechli by vás tam, až budete odtamtud vycházet, vytřeste prach zpod svých nohou jim na svědectví. [Amen, pravím vám, v den soudu bude snesitelněji zemi sodomské a gomorské než onomu městu.] “',
        12: 'Vyšli a vyhlásili, aby lidé činili pokání.',
        13: 'Vyháněli mnoho démonů, mazali olejem mnohé neduživé a uzdravovali.',
        14: 'Uslyšel to král Herodes, neboť se Ježíšovo jméno stalo známým. Říkalo se: „Jan Křtitel vstal z mrtvých, a proto v něm působí ty to moci.“',
        15: 'Jiní však říkali: „Je to Eliáš!“Jiní zase říkali: „Prorok -- jeden z těch proroků.“',
        16: 'Když to uslyšel Herodes, říkal: „Jan, kterého jsem já sťal, vstal [z mrtvých].“',
        17: 'Neboť sám Herodes dal Jana zajmout a spoutat ve vězení kvůli Herodiadě, ženě svého bratra Filipa, protože se s ní oženil.',
        18: 'Jan totiž Herodovi říkal: „Nesmíš mít ženu svého bratra!“',
        19: 'A Herodias to měla proti němu a chtěla ho zabít, ale nemohla.',
        20: 'Herodes se totiž Jana bál, věděl, že je muž spravedlivý a svatý, a ochraňoval ho. Mnohdy, když ho vyslechl, ⌈byl v úzkých, ale⌉ rád mu naslouchal.',
        21: 'Vhodný den nastal, když Herodes o svých narozeninách uspořádal hostinu pro své velmože, vojevůdce a přední muže z Galileje.',
        22: 'Tu vešla ⌈dcera té Herodiady⌉, zatančila a Herodovi i jeho spolustolovníkům se zalíbila. Král té dívce řekl: „Požádej mě, oč chceš, a dám ti to.“',
        23: 'A zapřísahal se jí: „O cokoliv bys mě požádala, to ti dám, až do polovice svého království.“',
        24: 'I vyšla a řekla své matce: „Oč bych měla požádat?“Ona řekla: „O hlavu Jana Křtitele!“',
        25: 'A hned spěšně vešla ke králi a požádala ho: „Chci, abys mi hned dal na míse hlavu Jana Křtitele!“',
        26: 'Král se velmi zarmoutil, ale kvůli těm přísahám a spolustolovníkům ji nechtěl odmítnout.',
        27: 'Král hned poslal kata a nařídil přinést Janovu hlavu. Ten odešel a sťal ho ve vězení,',
        28: 'přinesl na míse jeho hlavu a dal ji té dívce a dívka ji dala své matce.',
        29: 'Když to uslyšeli jeho učedníci, přišli, vzali jeho mrtvé tělo a uložili je do hrobu.',
        30: 'Apoštolové se shromáždili k Ježíšovi a oznámili mu všechno, co činili i co učili.',
        31: 'Řekl jim: „Pojďte vy sami stranou na opuštěné místo a trochu si odpočiňte.“Mnozí totiž stále přicházeli a odcházeli, neměli ani čas se najíst.',
        32: 'Odjeli tedy v lodi do ústraní na opuštěné místo.',
        33: 'Mnozí je uviděli odjíždět a poznali je; seběhli se tam pěšky ze všech měst a předešli je.',
        34: 'Když vystoupil a uviděl veliký zástup, byl nad nimi hluboce pohnut, protože byli jako ovce, které nemají pastýře. A začal je učit mnohým věcem.',
        35: 'Když už se připozdilo, přistoupili k němu jeho učedníci a říkali: „Toto místo je opuštěné a je již pozdě.',
        36: 'Propusť je, aby odešli do okolních statků a vesnic a nakoupili si něco k jídlu.“',
        37: 'On jim však odpověděl: „Vy jim dejte najíst!“Řekli mu: „Když odejdeme a nakoupíme za dvě stě denárů chleby, dáme jim najíst?“',
        38: 'On jim řekl: „Kolik máte chlebů? Jděte [a] podívejte se.“Když to zjistili, řekli: „Pět a dvě ryby.“',
        39: 'Nařídil jim, aby všechny usadili po skupinách na zelenou trávu.',
        40: 'Uložili se do řad po stu a do řad po padesáti.',
        41: 'Vzal těch pět chlebů a dvě ryby, vzhlédl k nebi, požehnal a rozlámal chleby a dával [svým] učedníkům, aby jim je předkládali. Také ty dvě ryby rozdělil všem.',
        42: 'Všichni jedli a nasytili se.',
        43: 'A sebrali plných dvanáct nůší úlomků chleba i ryb.',
        44: 'Těch, kteří jedli [ty chleby], bylo pět tisíc mužů.',
        45: 'A hned přinutil své učedníky, aby nastoupili do lodi a jeli napřed na druhou stranu k Betsaidě, než on propustí zástup.',
        46: 'Rozloučil se s nimi a odešel na horu, aby se pomodlil.',
        47: 'A když nastal večer, loď [již] byla uprostřed moře a on sám na zemi.',
        48: 'Uviděl je, jak se trápí při veslování, neboť vítr vál proti nim. Okolo čtvrté noční hlídky přicházel k nim kráčeje po moři a chtěl ⌈je minout⌉.',
        49: 'Když ho uviděli, jak kráčí po moři, pomysleli si, že to je přízrak, a vykřikli.',
        50: 'Všichni ho totiž uviděli a vyděsili se. On s nimi hned promluvil a řekl jim: „Vzchopte se, to jsem já, nebojte se!“',
        51: 'A nastoupil k nim do lodi a vítr přestal. Byli ve svém nitru naprosto ohromeni [a divili se].',
        52: 'Neboť nepochopili, co jim bylo ukázáno na těch chlebech, ale jejich srdce bylo ztvrdlé.',
        53: 'Když se přeplavili k zemi, přišli do Genezaretu [a tam zakotvili].',
        54: 'Jakmile vystoupili z lodi, hned jej lidé poznali.',
        55: 'Oběhli celou tu krajinu a začali na lehátkách přinášet nemocné tam, kde slyšeli, že je.',
        56: 'A kamkoli vcházel do vesnic nebo do měst nebo do statků, kladli nemocné na tržiště a prosili ho, aby se směli dotknout aspoň třásní jeho šatu, a všichni, kdo se ho dotkli, byli uzdravováni.',
    },
    7: {
        1: 'Shromáždili se k němu farizeové a někteří z učitelů Zákona, kteří přišli z Jeruzaléma.',
        2: 'A uviděli některé z jeho učedníků, že jedí chleby nečistýma, to jest neomytýma rukama.',
        3: 'Farizeové a všichni Židé, držíce tradici starších, totiž nejedí, dokud si ⌈k zápěstí⌉ neumyjí ruce.',
        4: 'Když přijdou z tržiště, nejedí, jestliže se neomyjí. A je ještě mnoho jiného, co převzali a drží: omývání pohárů, džbánů, měděných nádob [a lehátek].',
        5: 'Farizeové a učitelé Zákona se ho ptali: „Proč tvoji učedníci nežijí podle tradice starších, ale jedí chléb nečistýma rukama?“',
        6: 'On jim však řekl: „Dobře prorokoval Izaiáš o vás pokrytcích, jak je napsáno: Tento lid mne ctí rty, ale jejich srdce je ode mne velmi daleko.',
        7: 'Marně mne však uctívají, vyučujíce nauky, jež jsou jen lidskými příkazy.',
        8: 'Opustili jste přikázání Boží a držíte tradici lidí.“',
        9: 'A říkal jim: „Krásně odmítáte přikázání Boží, abyste zachovali svou tradici.',
        10: 'Vždyť Mojžíš řekl: Cti svého otce a svou matku a kdo zlořečí otci nebo matce, ať zemře!',
        11: 'Vy však říkáte: Řekne–li člověk otci nebo matce: To z mého majetku, co by ti mohlo pomoci, je korbán, to jest dar určený Bohu,',
        12: 'již mu nedovolujete nic učinit pro [jeho] otce nebo [jeho] matku.',
        13: 'Rušíte Boží slovo svou tradicí, kterou jste předali, a takových podobných věcí činíte mnoho.“',
        14: '⌈Opět k sobě zavolal zástup⌉ a řekl jim: „Poslyšte mne všichni a pochopte.',
        15: 'Nic, co je vně člověka a vchází do něho, ho nemůže znečistit, ale co z člověka vychází, to je to, co ho znečišťuje.',
        16: '[Má–li kdo uši k slyšení, ať poslouchá.] “',
        17: 'A když od zástupu vešel do domu, ptali se ho jeho učedníci na to podobenství.',
        18: 'Řekl jim: „I vy jste tak nechápaví? Nerozumíte, že vše, co zvnějšku vchází do člověka, ho nemůže znečistit,',
        19: 'protože nevchází do jeho srdce, ale do břicha a vychází ⌈do záchodu?“Tak prohlásil za čistévšechny pokrmy.⌉',
        20: 'Říkal však: „To, co z člověka vychází, to člověka znečišťuje.',
        21: 'Neboť zevnitř ze srdce lidí vycházejí zlé myšlenky, smilstva, krádeže, vraždy,',
        22: 'cizoložství, hrabivost, špatnosti, lest, bezuzdnost, závist, urážky, pýcha, pošetilost.',
        23: 'Všechny tyto špatnosti vycházejí zevnitř a znečišťují člověka.“',
        24: 'Pak vstal a odešel odtamtud na území Týru [a Sidónu]. Vstoupil do jednoho domu a nechtěl, aby o tom někdo věděl; nemohl se však skrýt.',
        25: 'Ale uslyšela o něm žena, jejíž dcerka měla nečistého ducha; hned přišla a padla k jeho nohám.',
        26: 'Ta žena byla Řekyně, rodem Syrofeničanka, a prosila ho, aby toho démona z její dcery vyhnal.',
        27: 'Říkal jí: „Nech nejprve nasytit děti. Není správné vzít chléb dětem a hodit jej psům.“',
        28: 'Ona však odpověděla a říká mu: „ [Ano,] Pane, i psi pod stolem jedí z drobtů po dětech.“',
        29: 'Řekl jí: „Kvůli tomuto slovu jdi domů; ten démon z tvé dcery vyšel.“',
        30: 'Odešla do svého domu a zjistila, že dítě leží na lůžku a démon vyšel.',
        31: 'Ježíš odešel z území Týru a šel opět přes Sidón ke Galilejskému moři středem území Dekapole.',
        32: 'Přivedli k němu hluchého a špatně mluvícího člověka a prosili ho, aby na něho vložil ruku.',
        33: 'Vzal si ho stranou od zástupu, vložil své prsty do jeho uší, plivnul a dotkl se jeho jazyka,',
        34: 'vzhlédl k nebi, vzdychl a řekl mu: „Effatha“, což znamená: Otevři se.',
        35: 'A jeho uši se [hned] otevřely a bylo uvolněno pouto jeho jazyka a začal mluvit správně.',
        36: 'Ježíš jim nařídil, aby to nikomu neříkali; čím víc jim to však nařizoval, tím víc to rozhlašovali.',
        37: 'Byli převelice ohromeni a říkali: „Všechno dobře učinil. Dokonce činí, aby hluší slyšeli a němí mluvili.“',
    },
    8: {
        1: 'Když tam byl v těch dnech opět veliký zástup a neměli co jíst, zavolal si učedníky a řekl jim:',
        2: '„Jsem hluboce pohnut nad zástupem, protože již tři dny zůstávají se mnou a nemají co jíst.',
        3: 'A propustím–li je hladové domů, zemdlí na cestě; a někteří z nich přišli zdaleka.“',
        4: 'Jeho učedníci mu odpověděli: „Odkud by někdo mohl zde v pustině získat tolik chleba, aby nasytil tyto lidi?“',
        5: 'Ptal se jich: „Kolik máte chlebů?“Oni řekli: „Sedm.“',
        6: 'Nařídil zástupu posadit se na zem. Vzal těch sedm chlebů, vzdal díky, rozlámal a dával svým učedníkům, aby je předkládali; i předložili je zástupu.',
        7: 'Měli i několik rybiček; požehnal je a řekl, aby i tyto předkládali.',
        8: 'Pojedli a nasytili se a sebrali toho, co přebývalo, sedm košů úlomků.',
        9: '[Těch, kteří jedli,] bylo asi čtyři tisíce. Pak je propustil.',
        10: 'A hned vstoupil se svými učedníky na loď a přišel do oblastí Dalmanuthy.',
        11: 'Vyšli proti němu farizeové a začali se s ním přít. Žádali od něho znamení z nebe, aby ho zkoušeli.',
        12: 'Hluboce povzdechl svým duchem a řekl: „Proč toto pokolení hledá znamení? Amen, pravím vám, tomuto pokolení nebude dáno žádné znamení.“',
        13: 'A opustil je, opět vstoupil [do lodi] a odjel na druhou stranu.',
        14: 'Zapomněli vzít chleby; neměli s sebou na lodi víc než jeden chléb.',
        15: 'A on jim nařizoval: „Dávejte si pozor, varujte se kvasu farizeů a kvasu Herodova.“',
        16: 'I dohadovali se mezi sebou, že nemají chleby.',
        17: 'Zpozoroval to a řekl jim: „Proč se dohadujete, že nemáte chleby? Ještě nerozumíte ani nechápete? [Ještě] máte své srdce ztvrdlé?',
        18: 'Oči máte a nevidíte, uši máte a neslyšíte? Nepamatujete si,',
        19: 'když jsem rozlámal těch pět chlebů pro pět tisíc, kolik nůší plných úlomků jste sebrali?“Řekli mu: „Dvanáct.“',
        20: '„Když těch sedm pro čtyři tisíce, kolik naplněných košů úlomků jste sebrali?“Řekli mu: „Sedm.“',
        21: 'A říkal jim: „Ještě nechápete?“',
        22: 'Pak přišli do Betsaidy. Přivedli k němu slepého a žádali ho, aby se ho dotkl.',
        23: 'Ježíš uchopil ruku toho slepého, vyvedl ho z vesnice, a když plivl do jeho očí a vložil na něho ruce, tázal se ho: „Vidíš něco?“',
        24: 'On vzhlédl a říkal: „Vidím lidi, vidím je jako stromy, a chodí.“',
        25: 'Pak opět vložil ruce na jeho oči a on prohlédl, jeho zrak byl obnoven a viděl všechno zřetelně.',
        26: 'A poslal ho domů se slovy: „Do vesnice teď nevstupuj [ani to nikomu ve vesnici neřekni]!“',
        27: 'Ježíš se svými učedníky vyšel do vesnic Cesareje Filipovy. Cestou se svých učedníků ptal: „Za koho mne lidé pokládají?“',
        28: 'Oni mu řekli: „ Někteří za Jana Křtitele, jiní za Eliáše a jiní za jednoho z proroků.“',
        29: 'A on se jich tázal: „ A za koho mne pokládáte vy?“Petr mu odpovídá: „Ty jsi Mesiáš.“',
        30: 'Přísně jim domluvil, aby to o něm nikomu neříkali.',
        31: 'A začal je učit, že Syn člověka musí mnoho vytrpět a být zavržen od starších, velekněží a učitelů Zákona, být zabit a po třech dnech vstát z mrtvých.',
        32: 'A mluvil o tom otevřeně. Petr si ho vzal stranou a začal ho kárat.',
        33: 'Když se však Ježíš otočil a uviděl své učedníky, pokáral Petra a řekl: „Jdi ode mne, satane, protože nemáš na mysli věci Boží, ale věci lidské.“',
        34: 'A zavolal si zástup se svými učedníky a řekl jim: „Chce–li kdo jít za mnou, ať zapře sám sebe, vezme svůj kříž a následuje mne.',
        35: 'Neboť kdo by chtěl svou duši zachránit, zahubí ji; kdo by však zahubil svou duši kvůli [mně a] evangeliu, zachrání ji.',
        36: 'Vždyť co člověku prospěje, získá–li celý svět, ale své duši uškodí?',
        37: 'Neboť co může dát člověk výměnou za svou duši?',
        38: 'Kdo by se styděl za mne a za má slova v tomto cizoložném a hříšném pokolení, za toho se bude stydět i Syn člověka, když přijde ve slávě svého Otce se svatými anděly.“',
    },
    9: {
        1: 'A říkal jim: „Amen, pravím vám, že jsou někteří z těch, kdo zde stojí, kteří určitě neokusí smrti, dokud neuvidí Boží království, přišlé v moci.“',
        2: 'A po šesti dnech vzal Ježíš s sebou Petra, Jakuba a Jana a je jediné vyvedl na vysokou horu, kde byli sami. A byl před nimi proměněn.',
        3: 'Jeho šaty se rozzářily a velmi zbělely, tak jak by je žádný bělič na zemi nemohl vybělit.',
        4: 'A ukázal se jim Eliáš s Mojžíšem a rozmlouvali s Ježíšem.',
        5: 'Petr ⌈na to⌉ Ježíšovi řekl: „Rabbi, je pro nás dobré tu být. Udělejme tři stánky, tobě jeden, Mojžíšovi jeden a Eliášovi jeden.“',
        6: 'Nevěděl totiž, co by na to řekl, neboť se velmi vyděsili.',
        7: 'A objevil se oblak a zastiňoval je, a z oblaku se ozval hlas: „Toto je můj Syn, ten Milovaný, poslouchejte ho.“',
        8: 'A náhle, když se rozhlédli, neviděli u sebe již nikoho, kromě samotného Ježíše.',
        9: 'A když sestupovali z hory, nařídil jim, aby to, co spatřili, nikomu nevypravovali, dokud Syn člověka nevstane z mrtvých.',
        10: 'Chytili se toho slova a mezi sebou se tázali, co to znamená vstát z mrtvých.',
        11: 'A ptali se ho: „Proč učitelé Zákona říkají, že nejprve musí přijít Eliáš?“',
        12: 'On jim říkal: „Nejprve opravdu přijde Eliáš a všechno obnoví. Ale jak to, že je napsáno o Synu člověka, že má mnoho vytrpět a být znevážen?',
        13: 'Avšak pravím vám, že Eliáš již nejen přišel, ale také mu učinili, co chtěli, jak je o něm napsáno.“',
        14: 'A když přišli k učedníkům, uviděli kolem nich veliký zástup a učitele Zákona, jak se s nimi přou.',
        15: 'A hned ⌈všichni v zástupu⌉, jakmile ho uviděli, byli velmi překvapeni; běželi k němu a zdravili ho.',
        16: 'I zeptal se jich: „O čem se s nimi přete?“',
        17: 'A jeden člověk ze zástupu mu odpověděl: „Učiteli, přivedl jsem k tobě svého syna, který má němého ducha.',
        18: 'Kdekoli se ho zmocní, trhá jím, a on pění, skřípe zuby a strne. Řekl jsem tvým učedníkům, aby ho vyhnali, ale nemohli.“',
        19: 'On jim na to říká: „Ach, pokolení nevěřící, jak dlouho ještě budu u vás? Jak dlouho ještě vás budu snášet? Při veďte ho ke mně.“',
        20: 'I přivedli ho k němu. Jakmile ho duch spatřil, ihned s ním zalomcoval, chlapec padl na zem, válel se a měl pěnu u úst.',
        21: 'Ježíš se zeptal jeho otce: „Jak je to dlouho, co se mu to stává?“On řekl: „Od dětství.',
        22: 'Často ho hodil i do ohně a do vody, aby ho zahubil. Avšak můžeš–li něco udělat, slituj se nad námi a pomoz nám.“',
        23: 'Ježíš mu řekl: „Můžeš–li! Všechno je možné tomu, kdo věří.“',
        24: 'Otec toho chlapce hned vykřikl a říkal: „Věřím, pomáhej mé nevíře!“',
        25: 'Když Ježíš uviděl, že se sbíhá zástup, pohrozil tomu nečistému duchu: „Duchu němý a hluchý, já ti přikazuji, vyjdi z něho a už do něho nikdy nevstupuj!“',
        26: 'Ten vykřikl a silně jím zalomcoval a vyšel. Chlapec zůstal jako mrtvý, takže mnozí říkali, že zemřel.',
        27: 'Ježíš uchopil jeho ruku, probudil ho a on vstal.',
        28: 'Když Ježíš vešel do domu, jeho učedníci se ho v soukromí ptali: „Proč jsme ho nemohli vyhnat my?“',
        29: 'Řekl jim: „Tento rod nemůže vyjít jinak, než v modlitbě [a půstu].“',
        30: 'A vyšli odtamtud a procházeli Galileou a nechtěl, aby ho někdo poznal.',
        31: 'Vyučoval totiž své učedníky a říkal jim: „Syn člověka je vydáván do rukou lidí a ti ho zabijí. A až bude zabit, ⌈po třech dnech⌉ vstane.“',
        32: 'Oni však tomu výroku nerozuměli, ale báli se ho zeptat.',
        33: 'A přišli do Kafarnaum. Když byl v domě, tázal se jich: „O čem jste cestou hovořili?“',
        34: 'Oni však mlčeli, neboť se cestou mezi sebou dohadovali, kdo je největší.',
        35: 'Posadil se, zavolal Dvanáct a řekl jim: „Chce–li být někdo první, bude poslední ze všech a služebník všech.“',
        36: 'A vzal dítě a postavil je doprostřed nich; pak je vzal do náručí a řekl jim:',
        37: '„Kdokoli přijme jedno z takových dětí na základě mého jména, mne přijímá; a kdo by mne přijímal, nepřijímá mne, ale toho, který mne poslal.“',
        38: 'Jan mu říkal: „Učiteli, viděli jsme někoho, jak ve tvém jménu vyhání démony, a bránili jsme mu v tom, protože nechodil s námi.“',
        39: 'Ježíš však řekl: „Nebraňte mu, neboť není nikdo, kdo na základě mého jména učiní mocný čin, aby o mně mohl brzy nato promluvit zle.',
        40: 'Vždyť kdo není proti nám, je pro nás.',
        41: 'Neboť kdo by vám dal napít číši vody proto, že jste Kristovi, amen, pravím vám, že určitě nepřijde o svou odměnu.“',
        42: '„Ale pro toho, kdo by svedl k hříchu jednoho z těchto maličkých, kteří věří [ve mne], by bylo mnohem lepší, kdyby mu přivázali velký mlýnský kámen na krk a hodili ho do moře.',
        43: 'Svádí–li tě tvá ruka, utni ji. Lépe je pro tebe do života vejít zmrzačený, než mít obě ruce a odejít do Gehenny do neuhasitelného ohně,',
        44: '[kde jejich červ neumírá a oheň nehasne].',
        45: 'A svádí–li tě tvá noha, utni ji. Lepší je pro tebe do života vejít chromý, než mít obě nohy a být hozen do Gehenny,',
        46: '[kde jejich červ neumírá a oheň nehasne].',
        47: 'A svádí–li tě tvé oko, vyjmi je. Lépe je pro tebe do Božího království vejít jednooký, než mít obě oči a být hozen do Gehenny,',
        48: 'kde jejich červ neumírá a oheň nehasne.',
        49: 'Neboť každý bude osolen ohněm [a každá oběť bude osolena solí].',
        50: 'Sůl je dobrá. Kdyby se však sůl stala neslanou, čím ji ochutíte? Mějte sůl v sobě a žijte mezi sebou pokojně.“',
    },
    10: {
        1: 'Vstal odtamtud a přišel na území Judska a Zajordání. A scházely se k němu opět zástupy a jak byl zvyklý, zase je učil.',
        2: 'A přišli farizeové, aby ho pokoušeli. Ptali se ho, je–li muži dovoleno propustit svou ženu.',
        3: 'On jim odpověděl: „Co vám přikázal Mojžíš?“',
        4: 'Oni pak řekli: „Mojžíš dovolil napsat rozlukový list a propustit.“',
        5: 'Ježíš jim řekl: „Pro tvrdost vašeho srdce vám napsal toto přikázání.',
        6: 'Od počátku stvoření je [Bůh] učinil jako muže a ženu.',
        7: 'Proto opustí člověk svého otce i matku [a přilne ke své ženě].',
        8: 'A budou ti dva jedno tělo, takže již nejsou dva, ale jedno tělo.',
        9: 'Co tedy Bůh spojil, ať člověk neodděluje.“',
        10: 'V domě se ho na to učedníci opět ptali.',
        11: 'Řekl jim: „Kdo by propustil svou ženu a oženil se s jinou, cizoloží vůči ní.',
        12: 'A jestliže by ona propustila svého muže a provdala se za jiného, cizoloží.“',
        13: 'A přinášeli k němu děti, aby se jich dotkl. Učedníci je však pokárali.',
        14: 'Když to Ježíš uviděl, rozhořčil se a řekl jim: „Nechte děti přicházet ke mně, nebraňte jim, neboť takových je Boží království.',
        15: 'Amen, pravím vám, kdo nepřijme Boží království jako dítě, jistě do něho nevstoupí.“',
        16: 'A bral je do náručí, vkládal na ně ruce a žehnal [jim].',
        17: 'A když vycházel na cestu, přiběhl jeden člověk, poklekl před ním a ptal se ho: „Dobrý učiteli, co mám učinit, abych získal věčný život?“',
        18: 'Ježíš mu řekl: „Proč mne nazýváš dobrým? Nikdo není dobrý, jen jediný: Bůh.',
        19: 'Přikázání znáš: Abys nezabil, nezcizoložil, neukradl, nevydal křivé svědectví, [nepodvedl]; cti svého otce a matku.“',
        20: 'On mu řekl: „Učiteli, toto všechno zachovávám od svého mládí.“',
        21: 'Ježíš na něho pohlédl, ⌈zamiloval si ⌉ ho a řekl mu: „Jedno ti chybí: Jdi, prodej všechno, co máš, a dej chudým a budeš mít poklad v nebi; pak přijď a následuj mne.“',
        22: 'On se nad tím slovem zachmuřil a se zármutkem odešel, neboť měl mnoho majetku.',
        23: 'Ježíš se rozhlédl a řekl svým učedníkům: „Jak těžko vcházejí do Božího království ti, kteří mají majetek.“',
        24: 'Učedníci se při jeho slovech děsili. Ježíš jim zase na to řekl: „Děti, jak nesnadné je [pro ty, kteří spoléhají na majetek,] vejít do Božího království.',
        25: 'Snadnější je, aby velbloud prošel uchem jehly, než aby bohatý vešel do Božího království.“',
        26: 'Oni byli velice ohromeni a říkali ⌈ si mezi sebou⌉: „A kdo může být zachráněn?“',
        27: 'Ježíš na ně pohleděl a řekl: „U lidí je to nemožné, ale ne u Boha. Neboť u Boha je možné všechno.“',
        28: 'Petr mu začal říkat: „Hle, my jsme opustili všechno a následujeme tě.“',
        29: 'Ježíš říkal: „Amen, pravím vám, není nikdo, kdo opustil dům nebo bratry nebo sestry nebo matku nebo otce nebo děti nebo pole kvůli mně a kvůli evangeliu,',
        30: 'aby nyní v tomto období nedostal stokrát více domů, bratrů a sester, matek a dětí a polí s pronásledováními a v přicházejícím věku život věčný.',
        31: 'Mnozí první budou poslední a poslední první.“',
        32: 'Byli na cestě, vystupovali do Jeruzaléma a Ježíš šel před nimi; a děsili se a ti, kteří je doprovázeli, se báli. Opět si k sobě vzal Dvanáct a začal jim říkat, co se mu má přihodit:',
        33: '„Hle, vystupujeme do Jeruzaléma; Syn člověka bude vydán velekněžím a učitelům Zákona a odsoudí ho k smrti a vydají ho pohanům.',
        34: 'Budou se mu posmívat, plivat na něho, zbičují ho a zabijí; a po třech dnech vstane z mrtvých.“',
        35: 'Přistoupili k němu Jakub a Jan, synové Zebedeovi, a řekli mu: „Učiteli, chceme, abys nám učinil, o cokoli tě požádáme.“',
        36: 'On pak jim řekl: „Co chcete, abych vám učinil?“',
        37: 'Oni mu řekli: „Dej nám, abychom se ve tvé slávě posadili jeden po tvé pravici a jeden po tvé levici.“',
        38: 'Ježíš jim řekl: „Nevíte, co žádáte. Můžete pít kalich, který já piji, nebo být pokřtěni křtem, kterým já jsem křtěn?“',
        39: 'Oni mu řekli: „Můžeme.“Ježíš jim řekl: „Kalich, který já piji, budete pít a křtem, kterým já jsem křtěn, budete křtěni.',
        40: 'Není však má věc, dát někomu usednout po mé pravici nebo levici, ale usednou tam ti, pro které je to připraveno.“',
        41: 'Když to uslyšelo těch deset, začali být na Jakuba a Jana rozmrzelí.',
        42: 'Ježíš si je zavolal a řekl jim: „Víte, že ti, kteří se zdají být vládci pohanů, panují nad nimi a jejich velcí nad nimi ⌈vykonávají svou svrchovanou moc⌉.',
        43: 'Avšak ne tak je tomu mezi vámi, ale kdo by se chtěl mezi vámi stát velkým, bude vaším služebníkem;',
        44: 'a kdo by chtěl být mezi vámi první, bude otrokem všech.',
        45: 'Vždyť ani Syn člověka nepřišel, aby si nechal posloužit, ale aby posloužil a dal svůj život jako výkupné za mnohé.“',
        46: 'Přišlido Jericha. A když se svými učedníky a dosti velikým zástupem vycházel z Jericha, seděl u cesty syn Timaiův, Bartimaios, slepý žebrák.',
        47: 'A když uslyšel, že je to Ježíš Nazaretský, začal křičet: „Synu Davidův, Ježíši, smiluj se nade mnou!“',
        48: 'Mnozí mu přísně domlouvali, aby zmlkl, ale on o to víc křičel: „Synu Davidův, smiluj se nade mnou!“',
        49: 'Ježíš se zastavil a řekl: „Zavolejte ho.“Zavolali toho slepého a řekli mu: „Vzchop se, vstaň, volá tě!“',
        50: 'On odhodil svůj plášť, vyskočil a přišel k Ježíšovi.',
        51: 'Ježíš mu odpověděl: „Co chceš, abych ti učinil?“Slepý mu řekl: „Rabbuni, ať vidím!“',
        52: 'A Ježíš mu řekl: „Jdi, tvá víra tě uzdravila.“A hned prohlédl a šel tou cestou za ním.',
    },
    11: {
        1: 'A když se přiblížili k Jeruzalému, k Betfage a Betanii u Olivové hory, poslal dva ze svých učedníků',
        2: 'a řekl jim: „Jděte do protější vesnice, a hned jak do ní vejdete, naleznete uvázané oslátko, na které se ještě nikdo z lidí neposadil. Odvažte je a přiveďte.',
        3: 'A jestliže vám někdo řekne: Co to děláte? řekněte: ⌈ Pán je potřebuje a hned je sem zase pošle. ⌉“',
        4: 'Odešli a nalezli oslátko uvázané venku na ulici u dveří a odvázali je.',
        5: 'A někteří z těch, kteří tam stáli, jim říkali: „Co to děláte, že odvazujete to oslátko?“',
        6: 'Oni jim řekli, jak řekl Ježíš, a ti je nechali.',
        7: 'A přivedli oslátko k Ježíšovi, hodili na ně svá roucha a on se na ně posadil.',
        8: 'A mnozí rozprostřeli na cestu svá roucha, jiní pak ratolesti, které nařezali na polích.',
        9: 'Ti, kteří šli vpředu, i ti, kteří šli za ním, křičeli: „Hosana! Požehnaný, který přichází ve jménu Pána!',
        10: 'Požehnané přicházející království našeho otce Davida! Hosana na výsostech!“',
        11: 'A vstoupil do Jeruzaléma do chrámu a rozhlédl se po všem. Protože již bylo pozdě, vyšel s Dvanácti do Betanie.',
        12: 'Když následujícího dne vyšli z Betanie, dostal hlad.',
        13: 'A z dálky uviděl fíkovník, který měl listí, a přišel, zdali na něm něco nenalezne. Když k němu přišel, nenalezl nic, jen listí; nebylo totiž období fíků.',
        14: 'I řekl mu: „Ať již navěky z tebe nikdo ovoce nejí!“A jeho učedníci to slyšeli.',
        15: 'A přišli do Jeruzaléma. Vešel do chrámu a začal vyhánět ty, kteří v chrámu prodávali a kupovali, a zpřevracel stoly směnárníků a sedadla prodavačů holubů.',
        16: 'A nedovoloval, aby někdo skrze chrám pronesl nějaké zboží.',
        17: 'Učil a říkal jim: „Což není napsáno: Můj dům bude nazván domem modlitby pro všechny národy? Vy jste jej však učinili jeskyní lupičů.“',
        18: 'Uslyšeli to velekněží a učitelé Zákona a hledali, jak by ho zahubili, neboť se ho báli; celý ten zástup byl totiž nad jeho učením ohromen.',
        19: 'Když nastal večer, vycházeli ven z města.',
        20: 'A když šli ráno kolem, uviděli ten fíkovník uschlý od kořenů.',
        21: 'Petr se rozpomenul a řekl mu: „Rabbi, hleď, ten fíkovník, který jsi proklel, je uschlý.“',
        22: 'Ježíš jim na to řekl: „Mějte víru Boží.',
        23: 'Amen, pravím vám, že kdo by řekl této hoře: Zvedni se a vrhni se do moře a nezapochyboval by ve svém srdci, ale věřil by, že co říká, se děje, bude to mít.',
        24: 'Proto vám pravím: Věřte, že jste všechno, za cokoliv se modlíte a oč žádáte, přijali, a budete to mít.',
        25: 'A kdykoliv stojíte a modlíte se, odpouštějte, máte–li proti někomu něco, aby vám i váš Otec, který je v nebesích, odpustil vaše přestoupení.“',
        27: 'A přišli opět do Jeruzaléma, a když se procházel v chrámu, přišli k němu velekněží, učitelé Zákona a starší',
        28: 'a říkali mu: „V jaké pravomoci to činíš? A kdo ti dal tuto pravomoc, abys to činil?“',
        29: 'Ježíš jim řekl: „Zeptám se vás na jednu věc; odpovězte mi a řeknu vám, v jaké pravomoci to činím.',
        30: 'Křest Janův byl z nebe, nebo z lidí? Odpovězte mi.“',
        31: 'Dohadovali se mezi sebou:„Řekneme–li z nebe, řekne: Proč jste mu [tedy] neuvěřili?',
        32: 'Máme říci z lidí?“Báli se zástupu, neboť všichni skutečně měli za to, že Jan byl prorok.',
        33: 'Odpověděli tedy Ježíšovi: „Nevíme.“A Ježíš jim řekl: „Ani já vám nepovím, v jaké pravomoci tyto věci činím.“',
    },
    12: {
        1: 'A začal k nim mluvit v podobenstvích. „ Jeden člověk vysadil vinici, obehnal zdí, vykopal jámu pro lis, vystavěl věž, pronajal ji vinařům a odcestoval.',
        2: 'V stanovený čas poslal k vinařům otroka, aby pře vzal od vinařů díl z úrody vinice.',
        3: 'Chytili ho, zbili a poslali s prázdnou.',
        4: 'Znovu k nim poslal jiného otroka a toho zranili na hlavě a potupili.',
        5: 'Poslal jiného, toho zabili; poslal i mnoho dalších, z nichž některé bili, jiné zabíjeli.',
        6: 'Měl ještě jednoho, [svého] milovaného syna. Naposled k nim poslal jeho a říkal: ⌈Zastydí se před mým synem.⌉',
        7: 'Ti vinaři si však řekli: To je dědic. Pojďte, zabijme ho a dědictví bude naše.',
        8: 'A chytili ho, zabili a vyhodili ho ven z vinice.',
        9: 'Co tedy učiní pán vinice? Přijde, zahubí ty vinaře a vinici dá jiným.',
        10: 'Ani toto Písmo jste nečetli: Kámen, který stavitelé po prozkoumání zavrhli, ten se stal hlavou úhlu.',
        11: 'Od Pána se to stalo a je to podivuhodné v našich očích?“',
        12: 'Chtěli se ho zmocnit, ale báli se zástupu. Poznali totiž, že to podobenství řekl proti nim. I opustili ho a odešli.',
        13: 'Poslali k němu některé z farizeů a herodiánů, aby ho chytili za slovo.',
        14: 'Přišli a řekli mu: „Učiteli, víme, že jsi pravdivý a nedbáš na nikoho, neboť ⌈nebereš ohled na postavení člověka⌉, ale v pravdě učíš cestě Boží. Je dovoleno dát daň císaři, nebo ne? Máme ji dát, či ji dát nemáme?“',
        15: 'On však znal jejich přetvářku a řekl jim: „Proč mne zkoušíte? Přineste mi denár, abych se podíval.“',
        16: 'Oni jej přinesli a Ježíš jim řekl: „Čí je ten obraz a nápis?“Oni mu řekli: „Císařův.“',
        17: 'Ježíš jim řekl: „Co je císařovo, odevzdejte císaři, a co je Boží, Bohu.“Velice se nad ním divili.',
        18: 'Přišli k němu saduceové, kteří říkají, že není vzkříšení, a ptali se ho:',
        19: '„Učiteli, Mojžíš nám napsal, že zemře–li něčí bratr a zanechá ženu, ale nezanechá dítě, aby si tu ženu vzal za manželku jeho bratr a vzbudil svému bratru potomka.',
        20: 'Bylo sedm bratrů. První si vzal ženu, zemřel a nezanechal potomka.',
        21: 'I druhý si ji vzal, zemřel a nezanechal potomka; a třetí stejně tak.',
        22: 'Těch sedm bratrů nezanechalo potomka; poslední ze všech zemřela i ta žena.',
        23: '[Když vstanou] při vzkříšení z mrtvých, komu z nich ta žena bude patřit? Vždyť všech sedm ji mělo za ženu.“',
        24: 'Ježíš jim říkal: „Nebloudíte právě proto, že neznáte Písma ani Boží moc?',
        25: 'Neboť když vstanou z mrtvých, nežení se ani se nevdávají, ale jsou jako andělé v nebesích.',
        26: 'O mrtvých pak, že vstávají, jste nečetli v Mojžíšově knize, jak mu u keře Bůh řekl: Já jsem Bůh Abrahamův, Bůh Izákův a Bůh Jákobův?',
        27: 'Není Bohem mrtvých, ale žijících. Velmi bloudíte!“',
        28: 'Tu přistoupil jeden z učitelů Zákona, který je uslyšel, jak se spolu dohadují. Když uviděl, že jim Ježíš dobře odpověděl, zeptal se ho: „Které přikázání je první ze všech?“',
        29: 'Ježíš odpověděl: „První je: Slyš, Izraeli, Pán, náš Bůh, Pán jediný jest',
        30: 'a budeš milovat Pána, svého Boha, z celého svého srdce, z celé své duše, z celé své mysli a z celé své síly.',
        31: 'Druhé je toto: Budeš milovat svého bližního jako sebe samého. Není jiné přikázání větší než tato.“',
        32: 'I řekl mu ten učitel Zákona: „Dobře, Učiteli, pravdivě jsi řekl, že je jediný a není jiného mimo něho',
        33: 'a milovat ho z celého srdce, z celého porozumění, z celé síly a milovat bližního jako sebe je větší než všechny celopaly a oběti.“',
        34: 'Když Ježíš uviděl, že odpověděl uváženě, řekl mu: „Nejsi daleko od Božího království.“A nikdo se ho již neodvažoval zeptat.',
        35: 'A když Ježíš odpověděl, začal vyučovat v chrámě: „Jak to, že učitelé Zákona říkají, že Kristus je syn Davidův?',
        36: 'Sám David řekl v Duchu Svatém: Řekl Pán mému Pánu: Seď po mé pravici, dokud nepoložím tvé nepřátele ⌈za podnož tvých nohou⌉.',
        37: 'Sám David ho nazývá Pánem; jakpak je tedy jeho synem?“A velký zástup mu rád naslouchal.',
        38: 'Ve svém učení říkal: „Varujte se učitelů Zákona, kteří se chtějí procházet v dlouhých rouchách a ⌈být pozdravováni⌉ na tržištích',
        39: 'a chtějí přední sedadla v synagogách a přední místa na hostinách.',
        40: 'Vyjídají domy vdov a okázale se dlouho modlí; ti dostanou větší odsouzení.“',
        41: '[Ježíš] se posadil proti pokladnici a pozoroval, jak zástup vhazuje do pokladnice měděné mince. A mnozí bohatí vhazovali hodně.',
        42: 'A přišla jedna chudá vdova a vhodila do ní dvě lepta, což je kvadrans.',
        43: 'Přivolal své učedníky a řekl jim: „Amen, pravím vám, že tato chudá vdova dala víc než všichni ostatní, kteří vhazovali do pokladnice.',
        44: 'Všichni totiž dali ze svého přebytku, tato však ze svého nedostatku dala vše, co měla, celé svoje živobytí.“',
    },
    13: {
        1: 'Když vycházel z chrámu, řekl mu jeden z jeho učedníků: „Učiteli, pohleď, jaké kameny a jaké stavby!“',
        2: 'Ježíš mu řekl: „Hledíš na tyto veliké stavby? Jistě [zde] nezůstane kámen na kameni, který by nebyl stržen.“',
        3: 'A když seděl na Olivové hoře naproti chrámu, ptali se ho v soukromí Petr, Jakub, Jan a Ondřej:',
        4: '„Pověz nám, kdy to bude a jaké bude znamení, až se to všechno začne naplňovat?“',
        5: 'Ježíš jim začal říkat: „Dávejte si pozor, aby vás někdo nesvedl.',
        6: '[Neboť] mnozí přijdou ⌈v mém jménu⌉ a budou říkat: Já jsem a svedou mnohé.',
        7: 'Když uslyšíte o válkách a válečné zvěsti, neděste se, musí to nastat, ale ještě ne bude konec.',
        8: 'Povstane totiž národ proti národu a království proti království. Na různých místech budou země třesení, budou hladomory [a nepokoje]. To bude začátek porodních bolestí.',
        9: 'Vy se však mějte na pozoru. Budou vás vydávat ⌈soudům a do synagog, budete biti a⌉ kvůli mně budete stavěni před vladaře a krále, jim na svědectví.',
        10: 'Všem národům musí být nejprve vyhlášeno evangelium.',
        11: 'A když vás budou vodit a vydávat, nestarejte se předem, co byste řekli, ale co by vám v tu hodinu bylo dáno, to mluvte. Neboť to nejste vy, kdo mluví, ale Duch Svatý.',
        12: 'A vydá na smrt bratr bratra a otec dítě, děti povstanou proti rodičům a usmrtí je.',
        13: 'A všichni vás budou nenávidět pro mé jméno. Kdo však vytrvá do konce, ten bude zachráněn.“',
        14: '„Když pak uvidíte ohavnost zpustošení postavenou, kde nemá být -- kdo čte, ať rozumí -- tehdy ti, kteří budou v Judsku, ať utíkají do hor.',
        15: 'Kdo bude na střeše, ať nesestupuje a nevstupuje dovnitř, aby si vzal něco ze svého domu.',
        16: 'A kdo bude na poli, ať se neobrací k věcem, které jsou vzadu, aby si vzal svůj plášť.',
        17: 'Běda těhotným a kojícím v oněch dnech!',
        18: 'Modlete se, aby [k vašemu útěku] nedošlo v zimě.',
        19: 'Neboť v oněch dnech bude takové soužení, jaké nenastalo od počátku stvoření, které stvořil Bůh, až do dneška a nikdy již nenastane.',
        20: 'A kdyby Pán nezkrátil ty dny, nebylo by zachráněno žádné tělo. Ale kvůli vyvoleným, které vyvolil, zkrátil ty dny.',
        21: 'A tehdy, když by vám někdo řekl: Hle, zde je Kristus!, [nebo:] Hle, tam!, nevěřte.',
        22: 'Neboť povstanou falešní kristové a falešní proroci a budou činit znamení a divy, aby, kdyby to bylo možné, svedli vyvolené.',
        23: 'Vy se tedy mějte na pozoru. Všechno jsem vám již předem řekl.“',
        24: '„Ale v oněch dnech, po onom soužení se zatmí slunce a měsíc nebude vydávat svou zář.',
        25: 'Hvězdy budou padat z nebe a mocnosti, které jsou v nebesích, se zatřesou.',
        26: 'A potom uvidí Syna člověka přicházejícího v oblacích s velikou mocí a slávou.',
        27: 'A tehdy pošle anděly a shromáždí své vyvolené ze čtyř větrů od nejzazšího konce země až po nejzazší konec nebe.“',
        28: '„Od fíkovníku se naučte podobenství: Když již jeho větev změkne a vyhání listy, víte, že léto je blízko.',
        29: 'Tak i vy, když uvidíte, že se tyto věci dějí, vězte, že je to blízko, přede dveřmi.',
        30: 'Amen, pravím vám, že určitě nepomine toto pokolení, dokud se toto všechno nestane.',
        31: 'Nebe a země pominou, ale má slova jistě nepominou.“',
        32: '„O tom dni či hodině nikdo neví, ani andělé v nebi, ani Syn, jedině Otec.',
        33: 'Dávejte si pozor, bděte [a modlete se], neboť nevíte, kdy je ten určený čas.',
        34: 'Jako člověk, který je na cestách: opustil svůj dům, dal svým otrokům plnou moc, každému jeho práci a dveřníkovi přikázal, aby bděl.',
        35: 'Bděte tedy, neboť nevíte, kdy Pán domu přijde, zda večer, či o půlnoci, nebo za kuropění, či před rozbřeskem,',
        36: 'aby nepřišel neočekávaně a nenalezl vás spící.',
        37: 'Co tedy říkám vám, říkám všem: Bděte!“',
    },
    14: {
        1: 'Byly dva dny před ⌈Hodem beránka⌉ a svátky nekvašených chlebů. Velekněží a učitelé Zákona hledali, jak by se ho lstí zmocnili, aby ho zabili.',
        2: 'Říkali totiž: „Ne ve svátek, aby snad nebylo pobouření lidu.“',
        3: 'Když byl v Betanii v domě Šimona Malomocného a byl u stolu, vešla žena, která měla alabastrovou nádobku pravého, velmi drahého nardového oleje; rozbila tu nádobku a olej vylila na jeho hlavu.',
        4: 'Někteří se mezi sebou rozhořčovali: „K čemu je ta ztráta oleje?',
        5: 'Vždyť se ten olej mohl prodat za víc než tři sta denárů a ty dát chudým!“A hněvali se na ni.',
        6: 'Ježíš řekl: „Nechte ji. Proč jí působíte těžkosti? Vykonala na mně dobrý skutek.',
        7: 'Vždyť chudé máte stále s sebou, a kdykoli chcete, můžete jim učinit dobře; mne však nemáte stále.',
        8: 'Učinila, co mohla; předem pomazala mé tělo olejem k pohřbu.',
        9: 'Amen, pravím vám, kdekoli po celém světě bude hlásáno [toto] evangelium, bude se na její památku mluvit také o tom, co ona učinila.“',
        10: 'A Juda Iškariotský, jeden z Dvanácti, odešel k velekněžím, aby jim ho vydal.',
        11: 'Když to uslyšeli, zaradovali se a slíbili mu dát peníze. I hledal vhodnou příležitost, jak by jim ho vydal.',
        12: 'Prvního dne nekvašených chlebů, když obětovali ⌈velikonočního beránka⌉, mu řekli jeho učedníci: „Kam chceš, abychom odešli a připravili ti k jídlu ⌈velikonočního beránka⌉?“',
        13: 'I poslal dva ze svých učedníků a řekl jim: „Jděte do města a potká vás člověk, který ponese džbán vody. Jděte za ním',
        14: 'a tam, kam vejde, řekněte hospodáři: Učitel říká: Kde je moje místnost, kde bych se svými učedníky pojedl ⌈velikonočního beránka⌉?',
        15: 'A on vám ukáže velkou horní místnost, již prostřenou a připravenou, a tam nám připravte jídlo.“',
        16: 'Učedníci vyšli, přišli do města a nalezli vše, jak jim řekl, i připravili ⌈velikonočního beránka⌉.',
        17: 'Když nastal večer, přišel s Dvanácti.',
        18: 'A když byli u stolu a jedli, Ježíš řekl: „Amen, pravím vám, že jeden z vás mne zradí, ten, který jí se mnou.“',
        19: 'Začali se rmoutit a jeden po druhém mu říkali: „Snad ne já?“',
        20: 'On jim řekl: „Jeden z Dvanácti, který se mnou namáčí v míse.',
        21: 'Syn člověka opravdu odchází, jak je o něm napsáno, běda však onomu člověku, skrze kterého je Syn člověka zrazován. ⌈Pro toho [by bylo] lépe, kdyby se byl⌉ nenarodil.“',
        22: 'A když jedli, vzal [Ježíš] chléb, požehnal a rozlomil, dal jim a řekl: „Vezměte, toto je mé tělo.“',
        23: 'Pak vzal kalich, vzdal díky a dal jim; a napili se z něj všichni.',
        24: 'A řekl jim: „Toto je má krev [nové] smlouvy, která se vylévá za mnohé.',
        25: 'Amen, pravím vám, že se [již více] nenapiji z plodu vinné révy až do onoho dne, kdy jej budu pít nový v Božím království.“',
        26: 'A zazpívali chvalozpěv a vyšli na Olivovou horu.',
        27: 'A Ježíš jim řekl: „Všichni [ode mne této noci] odpadnete, neboť je napsáno: Budu bít pastýře a ovce stáda se rozptýlí.',
        28: 'Ale po svém vzkříšení vás předejdu do Galileje.“',
        29: 'Petr mu říkal: „I kdyby všichni odpadli, já však ne!“',
        30: 'A Ježíš mu řekl: „Amen, pravím tobě, že dnes, této noci, dříve než kohout [dvakrát] zakokrhá, právě ty mne třikrát zapřeš.“',
        31: 'On však tím více říkal: „I kdybych s tebou musel zemřít, určitě tě nezapřu.“Stejně mluvili i ostatní.',
        32: 'I přicházejí k místu jménem Getsemane. Říká svým učedníkům: „Posaďte se zde, než se pomodlím.“',
        33: 'A vzal s sebou Petra, Jakuba a Jana a začal se děsit a znepokojovat.',
        34: 'Říká jim: „Má duše je smutná až k smrti. Zůstaňte zde a bděte!“',
        35: 'Trochu poodešel, padal na zem a modlil se, aby ho, je–li to možné, tato hodina minula.',
        36: 'Říkal: „Abba, Otče, tobě je všechno možné, přenes tento kalich ode mne, ale ne, co chci já, ale co ty.“',
        37: 'A přišel a nalezl je spící. Říká Petrovi: „Šimone, spíš? Nemohl jsi jedinou hodinu bdít?',
        38: 'Bděte a modlete se, abyste nevešli do pokušení. Duch je sice ochotný, ale tělo slabé.“',
        39: 'A opět odešel a pomodlil se, říkaje stejnou prosbu.',
        40: 'A opět, když přišel, nalezl je spící; měli velmi těžká víčka a nevěděli, co by mu odpověděli.',
        41: 'A přichází po třetí a říká jim: „Ještě spíte a odpočíváte? To stačí. Přišla ta hodina, hle, Syn člověka je vydáván do rukou hříšníků.',
        42: 'Vstávejte, pojďme! Hle, ⌈přiblížil se ten, který mne zrazuje.⌉“',
        43: 'A hned, když ještě mluvil, přichází Juda, jeden z Dvanácti, a s ním zástup od velekněží, učitelů Zákona a starších, s meči a holemi.',
        44: 'Ten, který ho zrazoval, ⌈měl s nimi domluvené znamení⌉: „Koho políbím, ten to je. Zmocněte se ho a bezpečně odveďte!“',
        45: 'Když přišel, hned k němu přistoupil a řekl: „Rabbi!“A vroucně ho políbil.',
        46: 'Oni pak na něho vztáhli ruce a zmocnili se ho.',
        47: 'Jeden z okolostojících tasil meč, udeřil veleknězova otroka a uťal mu ucho.',
        48: 'Ježíš jim na to řekl: „Vyšli jste s meči a holemi jako na lupiče, abyste mne zatkli.',
        49: 'Den co den jsem vyučoval u vás v chrámě, a nezmocnili jste se mne. Ale ⌈musí se naplnit⌉ Písma.“',
        50: 'A všichni ho opustili a utekli.',
        51: 'Šel s ním nějaký mladík, který měl přes nahé tělo přehozený lněný šat, i zmocnili se ho.',
        52: 'On tam však zanechal lněný šat a utekl [od nich] nahý.',
        53: 'Ježíše odvedli k veleknězi a shromáždili se [k němu] všichni velekněží, starší a učitelé Zákona.',
        54: 'Petr došel zpovzdálí za ním až dovnitř do veleknězova dvora, seděl pak se služebníky a ohříval se u ohně.',
        55: 'Velekněží a celá velerada hledali proti Ježíšovi svědectví, aby ho odsoudili k smrti, ale nenalézali.',
        56: 'Neboť mnozí proti němu křivě svědčili, ale jejich svědectví nebyla stejná.',
        57: 'Někteří povstali a křivě proti němu svědčili:',
        58: '„My jsme ho uslyšeli, jak říká: Já zbořím tuto svatyni udělanou rukama a ve třech dnech vybuduji jinou, ne rukama udělanou.“',
        59: 'A ani tak jejich svědectví nebylo shodné.',
        60: 'I povstal uprostřed velekněz a zeptal se Ježíše: „Nic neodpovídáš? Co tito lidé proti tobě svědčí?“',
        61: 'On však mlčel a nic neodpovídal. Znovu se ho velekněz otázal a řekl mu: „Jsi ty Mesiáš, Syn Požehnaného?“',
        62: 'Ježíš řekl: „Já jsem. A spatříte Syna člověka sedícího po pravici Moci a přicházejícího s nebeskými oblaky.“',
        63: 'Velekněz roztrhl svá roucha a říká: „Nač ještě potřebujeme svědky?',
        64: 'Slyšeli jste rouhání. Jak se vám to jeví?“Všichni ho odsoudili, že je hoden smrti.',
        65: 'A někteří na něho začali plivat, zahalovat mu tvář, bít ho pěstmi a říkat mu: „Zaprorokuj!“A biřici ho zasypali ranami.',
        66: 'A zatímco byl Petr dole v nádvoří, přišla jedna z veleknězových služek.',
        67: 'Když uviděla Petra, jak se ohřívá, pohlédla na něj a řekla: „I ty jsi byl s Nazaretským, tím Ježíšem.“',
        68: 'On však zapřel: „Nevím ani nerozumím, co říkáš.“A vyšel ven do předního dvora [a kohout zakokrhal].',
        69: 'A když ho ta služka uviděla, začala opět říkat těm, kteří stáli poblíž: „Tento je z nich.“',
        70: 'On však opět zapíral. A za malou chvíli znovu ti, co stáli poblíž, říkali Petrovi: „Skutečně jsi jeden z nich, vždyť jsi také Galilejec.“',
        71: 'On se pak začal zaklínat a zapřísahat: „Neznám toho člověka, o kterém mluvíte.“',
        72: 'A [hned] kohout [podruhé] zakokrhal. Tu si Petr rozpomněl na výrok, jak mu Ježíš řekl: „Než kohout dvakrát zakokrhá, třikrát mne zapřeš,“a ⌈začal plakat⌉.',
    },
    15: {
        1: 'A hned časně zrána ⌈velekněží se staršími a učitelé Zákona⌉ -- celá velerada -- ⌈se poradili⌉, Ježíše spoutali, odvedli a vydali Pilátovi.',
        2: 'Pilát se ho otázal: „Ty jsi král Židů?“On mu odpověděl: „Ty říkáš.“',
        3: 'Velekněží ho velmi obviňovali.',
        4: 'Pilát se ho znovu zeptal: „Nic neodpovídáš? Podívej, z čeho všeho tě obviňují!“',
        5: 'Ježíš však již nic neodpověděl, takže se Pilát divil.',
        6: 'O svátcích jim propouštěl jednoho vězně, o kterého žádali.',
        7: 'Se vzbouřenci, kteří se při vzpouře dopustili vraždy, byl uvězněný muž zvaný Barabáš.',
        8: 'Zástup ⌈vystoupil k Pilátovi ⌉ a začal žádat, aby učinil, jak jim činíval.',
        9: 'Pilát jim odpověděl: „Chcete, abych vám propustil krále Židů?“',
        10: 'Uvědomoval si totiž, že ho [velekněží] vydali ze závisti.',
        11: 'Velekněží však podnítili zástup, aby jim raději propustil Barabáše.',
        12: 'Pilát jim zase na to říkal: „Co tedy [chcete,] abych učinil s [tím, kterého nazýváte] králem Židů?“',
        13: 'Oni opět zvolali: „Ukřižuj ho!“',
        14: 'Pilát jim říkal: „Co tedy udělal zlého?“Oni pak ještě silněji zvolali: „Ukřižuj ho!“',
        15: 'Pilát pak, chtěje vyhovět zástupu, jim propustil Barabáše; Ježíše dal zbičovat a vydal ho, aby byl ukřižován.',
        16: 'Vojáciho odvedli do dvora, to jest do pretoria, a svolali celý oddíl.',
        17: 'Oblékli mu purpur, upletli trnový věnec a nasadili mu jej',
        18: 'a začali ho zdravit: „Buď zdráv, králi Židů!“',
        19: 'Bili ho po hlavě rákos ovou holí, plivali na něj, poklekali a klaněli se mu.',
        20: 'Když se mu naposmívali, svlékli ho z purpuru a oblékli mu jeho šaty. Vyvedli ho, aby ho ukřižovali.',
        21: 'A přinutili kolemjdoucího Šimona z Kyrény, otce Alexandra a Rufa, jdoucího z pole, aby vzal jeho kříž.',
        22: 'Přivedli ho na místo zvané Golgota, což v překladu znamená Místo lebky.',
        23: 'Dávali mu [pít] víno smíchané s myrhou, ale on je nepřijal.',
        24: 'Pak jej ukřižovali a dělili si jeho šaty, losujíce o ně, kdo si co vezme.',
        25: 'Byla třetí hodina, když ho ukřižovali.',
        26: 'A byl ⌈napsán nápis o jeho vině⌉: Král Židů.',
        27: 'Spolu s ním byli ukřižováni dva lupiči, jeden po pravici a druhý po jeho levici.',
        28: '[Naplnilo se Písmo, které praví: Byl započten mezi bezzákonné.]',
        29: 'A kolemjdoucí ho uráželi, potřásali hlavou a říkali: „Ó, ty, který boříš svatyni a ve třech dnech ji stavíš!',
        30: 'Sestup s kříže a zachraň se!“',
        31: 'Podobně se i velekněží a učitelé Zákona mezi sebou posmívali a říkali: „Jiné zachránil, sebe zachránit nemůže.',
        32: 'Ať nyní Kristus, král Izraele, sestoupí s kříže, abychom uviděli a uvěřili.“Také ti, kteří byli ukřižováni spolu s ním, ho haněli.',
        33: 'A když nastala šestá hodina, padla tma na celou zemi až do deváté hodiny.',
        34: 'O deváté hodině Ježíš zvolal silným hlasem: „Eloi, Eloi, lema sabachthani?“což v překladu znamená: Můj Bože, můj Bože, proč jsi mne opustil?',
        35: 'A když to uslyšeli někteří z těch, kdo stáli poblíž, říkali: „Hle, volá Eliáše.“',
        36: 'Kdosi pak vyběhl, naplnil houbu octem, připevnil na rákos ovou hůl a dával mu pít se slovy: „Nechte ho, ať uvidíme, přijde–li Eliáš, aby ho sundal.“',
        37: 'Ježíš vydal mocný hlas a ⌈vydechl naposled ⌉.',
        38: 'A opona svatyně se roztrhla ve dví odshora až dolů.',
        39: 'Když setník, který stál blízko naproti němu, uviděl, že takto vydechl, řekl: „Tento člověk byl opravdu Boží Syn.“',
        40: 'Zdaleka se dívaly také ženy, mezi nimi Marie Magdalská a Marie, matka Jakuba mladšího a Josese, a Salome,',
        41: 'které chodily s ním a sloužily mu, když byl v Galileji, a mnoho jiných, které spolu s ním vystoupily do Jeruzaléma.',
        42: 'A když již nastal večer, poněvadž byl den přípravy, to jest den před sobotou,',
        43: 'přišel Josef z Arimatie, vážený člen rady, který také sám očekával Boží království. Osmělil se, vešel k Pilátovi a požádal o Ježíšovo tělo.',
        44: 'Pilát se podivil, že by byl již mrtev. Zavolal si setníka a otázal se ho, ⌈je–li to dlouho, co ⌉ zemřel.',
        45: 'A když se to od setníka dověděl, daroval mrtvé tělo Josefovi.',
        46: 'Ten nakoupil jemné plátno, sundal ho s kříže, zavinul tím plátnem a uložil ho v hrobce, která byla vytesána ve skále, a ke vchodu do hrobky přivalil kámen.',
        47: 'Marie Magdalská a Marie [matka] Josesova pozorovaly místo, kam byl uložen.',
    },
    16: {
        1: 'Když uplynula sobota, Marie Magdalská, Marie [matka] Jakubova a Salome nakoupily vonné látky, aby přišly a pomazaly ho.',
        2: 'A časně ráno prvního dne týdne, když vyšlo slunce, přicházely k hrobce.',
        3: 'A říkaly si: „Kdo nám odvalí kámen od vchodu do hrobky?“',
        4: 'A vzhlédly a vidí, že kámen je odvalen; byl totiž velmi veliký.',
        5: 'Když vstoupily do hrobky, spatřily mládence sedícího po pravé straně, oděného bílým rouchem, a vyděsily se.',
        6: 'On pak jim řekl: „Neděste se. Hledáte Ježíše Nazaretského, toho ukřižovaného. Byl vzkříšen z mrtvých, není tu. Hle, místo, kam ho položili.',
        7: 'Ale jděte a povězte jeho učedníkům i Petrovi: Jde před vámi do Galileje; tam ho spatříte, tak jak vám řekl.“',
        8: 'Vyšly a utekly od hrobky; zmocnilo se jich totiž třesení a byly zcela bez sebe. A nikomu nic neřekly, neboť se bály.',
        9: 'Ráno prvního dne týdne, když Ježíš vstal, ukázal se nejprve Marii Magdalské, od níž kdysi vyhnal sedm démonů.',
        10: 'Ona šla a oznámila to těm, kteří byli s ním a kteří teď plakali a truchlili.',
        11: 'A oni, když uslyšeli, že opět žije a že ho spatřila, neuvěřili.',
        12: 'Potom se v jiném způsobu ukázal dvěma z nich cestou, když šli na pole.',
        13: 'A oni odešli a oznámili to ostatním, ale ani těmto neuvěřili.',
        14: 'Nakonec se ukázal Jedenácti, když byli u stolu; pokáral jejich nevěru a tvrdost srdce, protože neuvěřili těm, kteří ho spatřili vzkříšeného [z mrtvých].',
        15: 'A řekl jim: „Jděte do celého světa a vyhlašte evangelium všemu stvoření.',
        16: 'Kdo uvěří a bude pokřtěn, bude zachráněn. Kdo neuvěří, bude odsouzen.',
        17: 'Tato znamení budou doprovázet ty, kteří uvěří: V mém jménu budou vyhánět démony, budou mluvit [novými] jazyky,',
        18: 'budou brát hady [do rukou] a vypijí–li něco smrtelného, nijak jim to neublíží. Na nemocné budou vzkládat ruce a budou se mít dobře.“',
        19: 'Potom, když jim to pověděl, byl Pán [Ježíš] vzat vzhůru do nebe a posadil se po pravici Boží.',
        20: 'Oni vyšli a vyhlásili všude evangelium, Pán pracoval s nimi a potvrzoval to slovo znameními, která je doprovázela. [Amen.]',
    },
}
